e":"uint256","name":"id","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"amount","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"released","type":"uint256"},{"indexed":false,"internalType":"uint64","name":"upTo","type":"uint64"}],"name":"Released","type":"event"},{"inputs":[],"name":"MAX_WIDTH_TICKS","outputs":[{"internalType":"uint32","name":"","type":"uint32"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"campaignCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"bytes32","name":"poolId","type":"bytes32"},{"internalType":"address","name":"rewardToken","type":"address"},{"internalType":"uint256","name":"perSecond","type":"uint256"},{"internalType":"uint256","name":"budget","type":"uint256"},{"internalType":"uint32","name":"minWidthTicks","type":"uint32"}],"name":"createCampaign","outputs":[{"internalType":"uint256","name":"id","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"distributor","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"id","type":"uint256"}],"name":"getCampaign","outputs":[{"components":[{"internalType":"bytes32","name":"poolId","type":"bytes32"},{"internalType":"address","name":"rewardToken","type":"address"},{"internalType":"uint256","name":"budget","type":"uint256"},{"internalType":"uint32","name":"minWidthTicks","type":"uint32"},{"internalType":"address","name":"funder","type":"address"},{"internalType":"uint256","name":"released","type":"uint256"},{"components":[{"internalType":"uint64","name":"from","type":"uint64"},{"internalType":"uint256","name":"perSecond","type":"uint256"}],"internalType":"struct RewardCampaigns.Rate[]","name":"rates","type":"tuple[]"}],"internalType":"struct RewardCampaigns.Campaign","name":"","type":"tuple"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"from","type":"uint256"},{"internalType":"uint256","name":"to","type":"uint256"}],"name":"getCampaigns","outputs":[{"components":[{"internalType":"bytes32","name":"poolId","type":"bytes32"},{"internalType":"address","name":"rewardToken","type":"address"},{"internalType":"uint256","name":"budget","type":"uint256"},{"internalType":"uint32","name":"minWidthTicks","type":"uint32"},{"internalType":"address","name":"funder","type":"address"},{"internalType":"uint256","name":"released","type":"uint256"},{"components":[{"internalType":"uint64","name":"from","type":"uint64"},{"internalType":"uint256","name":"perSecond","type":"uint256"}],"internalType":"struct RewardCampaigns.Rate[]","name":"rates","type":"tuple[]"}],"internalType":"struct RewardCampaigns.Campaign[]","name":"page","type":"tuple[]"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"","type":"address"}],"name":"isManager","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"owner","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256[]","name":"ids","type":"uint256[]"},{"internalType":"uint256[]","name":"emitted","type":"uint256[]"},{"internalType":"uint64","name":"upTo","type":"uint64"},{"internalType":"bytes32[][]","name":"proofs","type":"bytes32[][]"}],"name":"release","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"account","type":"address"},{"internalType":"bool","name":"active","type":"bool"}],"name":"setManager","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"_owner","type":"address"}],"name":"setOwner","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"id","type":"uint256"},{"internalType":"uint256","name":"perSecond","type":"uint256"}],"name":"setRate","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"id","type":"uint256"},{"internalType":"uint256","name":"emitted","type":"uint256"},{"internalType":"bytes32[]","name":"proof","type":"bytes32[]"}],"name":"settleRefund","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"details":"Each campaign has one funder, the manager who created it and deposited its whole budget. The engine never emits more than the budget, so the distributor can always be paid in full, and what was not emitted goes back to the funder once the campaign ended. More rewards for a pool are a new campaign on the same pool, so a budget never mixes the tokens of two wallets. The bot refuses campaign changes that would alter what an already published week emitted, and every change here takes effect from the block that makes it, so none can: - A campaign is never removed, and its pool, reward token, `minWidthTicks` and funder never change. Its budget   only drops, when a refund sends what the campaign cannot emit back to the funder. - A campaign starts when it is created, and a rate change applies from the block it is mined in. Rate history   is append-only; a rate of 0 ends the campaign for good, so its rates bound everything it can still emit. Reward tokens must transfer exactly the amount requested: fee-on-transfer and rebasing tokens are not supported. The registry records the nominal budget and every campaign of a token shares one balance, so such a token would pay one campaign's releases and refund out of the escrow of the others. Reward tokens must also never revert a transfer, so tokens with a pause, a blocklist or transfer hooks are not supported either. `release` pays every due campaign in one call, so one failing transfer would stop the release and the weekly root of every campaign on the chain, and a blocked funder would never get its refund. Managers are trusted team wallets. `createCampaign` checks neither the token nor that the pool uses the Seer hook, and the bot replays each pool from the hook deployment, so an older pool would stop it for every campaign.","errors":{"SafeERC20FailedOperation(address)":[{"details":"An operation with an ERC-20 token failed."}]},"events":{"CampaignSet(uint256,(bytes32,address,uint256,uint32,address,uint256,(uint64,uint256)[]))":{"details":"Snapshots the earning rules and budget. Subsequent payouts update `released` through `Released` only."},"Released(uint256,uint256,uint256,uint64)":{"params":{"upTo":"The cutoff supplied for this call, including corrections to earlier cutoffs."}}},"kind":"dev","methods":{"constructor":{"params":{"_distributor":"This chain's Universal Rewards Distributor.","_managers":"The initial managers.","_owner":"The owner of the registry, usually a Safe."}},"createCampaign(bytes32,address,uint256,uint256,uint32)":{"returns":{"id":"The id of the new campaign."}},"getCampaigns(uint256,uint256)":{"details":"Each campaign carries its whole rate history, so one call returning every campaign would outgrow an `eth_call` gas cap as campaigns accumulate. A `to` past the last campaign stops at it and an empty range returns nothing, so a reader pages with a fixed size from `campaignCount`."},"release(uint256[],uint256[],uint64,bytes32[][])":{"details":"Each total must be a release leaf of the root the distributor accepted, so it went through the distributor's timelock and its owner's veto like the claims it pays. The key that proposes roots therefore cannot pay out escrow at once, and every total is also bounded by the integral of the rates up to `upTo`."},"setRate(uint256,uint256)":{"details":"A rate is at most the budget, which fits in 128 bits, so `release` and `settleRefund` multiply it by a `uint64` span of seconds without overflowing; one overflowing campaign would revert the weekly release of every campaign on the chain."}},"stateVariables":{"MAX_WIDTH_TICKS":{"details":"`TickMath.MAX_TICK - TickMath.MIN_TICK` of Uniswap V4: no position is wider, so a larger minimum width would leave every position out and the campaign would never emit."}},"title":"RewardCampaigns","version":1},"userdoc":{"kind":"user","methods":{"createCampaign(bytes32,address,uint256,uint256,uint32)":{"notice":"Creates a campaign that emits `perSecond` from this block on, and deposits its whole `budget` from the caller, who must have approved this contract for it and becomes its funder."},"getCampaigns(uint256,uint256)":{"notice":"The campaigns with ids from `from` up to, but not including, `to`, in id order."},"release(uint256[],uint256[],uint64,bytes32[][])":{"notice":"Sends the distributor what campaigns `ids` emitted up to the weekly cutoff `upTo`, given as the cumulative `emitted` of each, so a repeated call sends nothing more. Anyone may call it."},"setOwner(address)":{"notice":"Transfers ownership. It takes effect at once."},"setRate(uint256,uint256)":{"notice":"Sets the rate from this block on. A rate of 0 ends the campaign for good: more rewards for the pool are a new campaign."},"settleRefund(uint256,uint256,bytes32[])":{"notice":"Returns the remaining escrow to the funder once the accepted distribution covers the end."}},"notice":"Liquidity reward campaigns of Seer's Uniswap V4 pools on this chain, and the escrow of their budgets. Rewards pay out on the pool's chain, so there is one registry per chain with pools, next to that chain's Morpho Universal Rewards Distributor. The weekly rewards bot (`packages/seer-pm-rewards`) rebuilds the campaigns from `CampaignSet` events up to each Monday cutoff and submits a root with what users can claim and what each campaign emitted. Once the distributor accepts that root, `release` pays the distributor the emitted totals it proves.","version":1}},"settings":{"compilationTarget":{"src/rewards/RewardCampaigns.sol":"RewardCampaigns"},"evmVersion":"cancun","libraries":